function uniqueRefList(values) {
  if (!Array.isArray(values)) throw new TypeError("Reference values must be an explicit array.");
  return Object.freeze([...new Set(values.filter(Boolean))]);
}

function nonEmptyString(value) {
  return typeof value === "string" && value.trim();
}

function factTupleFromMutationFact(fact) {
  if (typeof fact !== "object") throw new TypeError("Authored mutation fact must be an object.");
  const polarity = fact.pol == null ? AUTHORED_FACTS_POLICY.missingPolarity : textOrEmpty(fact.pol);
  return {
    s: canonicalizeValue("ref", textOrEmpty(fact.s)),
    p: canonicalizeValue("string", textOrEmpty(fact.p)),
    o: canonicalizeValue("string", textOrEmpty(fact.o)),
    pol: canonicalizeValue("string", polarity),
  };
}

function oneFactValue(facts, subject, predicate, helpers) {
  const matches = facts.filter(fact => fact.s === subject && fact.p === predicate);
  if (!matches.length) return "";
  if (matches.length === 1) return matches[0].o;
  helpers.failSemantic(helpers.mutationIssue(
    "invalid-generated-cluster",
    `Generated subject ${subject} must declare exactly one ${predicate}.`,
    { subject, predicate },
  ), { statusCode: 400 });
}

