function manyFactValues(facts, subject, predicate) {
  return facts.filter(fact => fact.s === subject && fact.p === predicate).map(fact => fact.o);
}

function firstCompatibleContract(candidates) {
  if (!candidates.length) return null;
  const first = candidates[0];
  const expected = signature(first);
  return candidates.every(candidate => signature(candidate) === expected) ? first : null;
}

function validateTimestampValue(value) {
  if (!ISO_TIMESTAMP_RE.test(String(value))) return "invalid timestamp; expected canonical ISO 8601 timestamp";
  if (!Number.isFinite(Date.parse(String(value)))) return "invalid timestamp; expected canonical ISO 8601 timestamp";
  return "";
}

function applyContractPolicy(contract, context) {
  const authored = contractSlotAuthoredPolicy(contract, context);
  const provided = resolveContractProviderPolicy(contract, context);
  if (authored === null && provided === null) return contract;
  const merged = { ...Object(authored), ...Object(provided) };
  const result = { ...contract };
  for (const field of MUTATION_CONTRACT_POLICY.stringFields) {
    if (Object.prototype.hasOwnProperty.call(merged, field)) result[field] = String(merged[field]);
  }
  for (const field of MUTATION_CONTRACT_POLICY.structuredFields) {
    if (Object.prototype.hasOwnProperty.call(merged, field)) result[field] = merged[field];
  }
  return result;
}

function removalChoiceDetails(values, projection) {
  return Object.freeze(values.map(value => {
    const normalized = String(value);
    const record = Object(projection[normalized]);
    const label = firstText([record.label, record.name, normalized]);
    return { value: normalized, label: label === normalized ? normalized : `${label} (${normalized})`, disabled: false, reason: "" };
  }));
}

function selectedReclassificationDefault(choices) {
  const enabled = choices.find(choice => !choice.disabled);
  if (enabled !== undefined) return enabled.value;
  if (choices.length > 0) return choices[0].value;
  return "";
}

function reclassificationChoiceDetails(prog, record, interfaces) {
  const authoredTypes = Array.isArray(record.isa) ? record.isa : [];
  const currentTypes = new Set(authoredTypes.filter(type => interfaces.has(type)));
  return knownInterfaceTypes(prog).map(type => {
    const iface = interfaces.get(type);
    if (iface === undefined) return { value: type, label: type, disabled: true, reason: "interface unavailable" };
    if (currentTypes.has(type)) return { value: type, label: type, disabled: false, reason: "" };
    const issues = reclassificationCompatibilityIssues(record, iface);
    return {
      value: type,
      label: type,
      disabled: issues.length > 0,
      reason: issues.length > 0 ? issues[0].reason : "",
    };
  });
}

function authoredInterfaceTypes(record, interfaces) {
  const types = Array.isArray(record.isa) ? record.isa : [];
  return Object.freeze(types.filter(type => interfaces.has(type)));
}

function reclassificationPreservedPredicates(record, targetIface) {
  const reserved = new Set(RECLASSIFICATION_POLICY.reservedPredicates);
  const targetSlots = new Set(targetIface.slots.filter(slot => !reserved.has(slot.predicate)).map(slot => slot.predicate));
  const openTarget = targetIface.mode === RECLASSIFICATION_POLICY.openMode;
  return Object.freeze(Object.keys(record)
    .filter(key => !reserved.has(key))
    .filter(predicate => openTarget ? true : targetSlots.has(predicate))
    .sort((left, right) => left.localeCompare(right)));
}

function visibleRecord(projection, subject) {
  const record = projection?.[subject];
  return record && typeof record === "object" && Array.isArray(record[POLICY.typeField]) ? record : null;
}

function incomingProjectionReferences(projection, targetSubject) {
  const normalizedProjection = projection === undefined ? EMPTY_PROJECTION : projection;
  const normalizedTarget = targetSubject === undefined ? POLICY.missingTargetSubject : targetSubject;
  const references = [];
  for (const [candidateSubject, record] of Object.entries(normalizedProjection)) {
    if (!visibleRecord(normalizedProjection, candidateSubject)) continue;
    if (candidateSubject === normalizedTarget) continue;
    references.push(...referencesFromRecord(candidateSubject, record, normalizedTarget));
  }
  return Object.freeze(references);
}

function slotForPredicate(iface, predicate) {
  const slot = iface?.slots.find(candidate => candidate[POLICY.slotPredicateField] === predicate);
  return slot === undefined ? null : slot;
}

function sameReferenceSet(left, right) {
  const a = [...uniqueRefList(left)].sort((x, y) => x.localeCompare(y));
  const b = [...uniqueRefList(right)].sort((x, y) => x.localeCompare(y));
  return a.length === b.length && a.every((value, index) => value === b[index]);
}

function restoreSlot(iface, predicate) {
  const slot = iface.slots.find(candidate => candidate.predicate === predicate);
  return slot === undefined ? null : slot;
}

function slotActionMode(slot, record, requestedMode) {
  if (requestedMode !== POLICY.autoMode) return requestedMode;
  const present = Object.hasOwn(record, slot.predicate);
  return [slotIsMany(slot), !present].includes(true) ? POLICY.addMode : POLICY.setMode;
}

function fallbackRefPrompt(contract, currentContext) {
  const compatibleType = typeof contract.compatibleRefType === "string" ? contract.compatibleRefType : "";
  if (!compatibleType) return {};
  const target = currentContext ? `${compatibleType} visible in ${currentContext}` : compatibleType;
  return { fallbackMessage: `No compatible ${target} is currently visible. Enter a reference manually.` };
}

function editablePromptDefault(contract, record, typedRecord, requestedPredicate, adding) {
  if (contract.viaAssignment) return Object.hasOwn(record, requestedPredicate) ? String(record[requestedPredicate]) : "";
  if (adding && !Object.hasOwn(record, contract.slot.predicate)) return currentCanonicalDefault(contract.slot, {}, {});
  return currentCanonicalDefault(contract.slot, record, typedRecord);
}

function editablePromptMode(contract, requestedMode, requestedPredicate) {
  const adding = [requestedMode === POLICY.addMode, !contract.viaAssignment && slotIsMany(contract.slot)].includes(true);
  return {
    adding,
    mode: adding ? POLICY.addMode : POLICY.setMode,
    fieldLabel: contract.viaAssignment ? contract.slot.predicate : requestedPredicate,
  };
}

function editablePromptEditor(contract, choiceDetails) {
  const slot = contract.slot;
  const spec = contractEditorSpec(contract);
  const editorKind = choiceDetails.length
    ? POLICY.choiceEditor
    : firstText([spec?.editorKind, spec?.canonicalValueType, slot.valueType]);
  const valueType = firstText([
    spec?.canonicalValueType,
    spec?.editorKind === POLICY.timestampEditor ? POLICY.timestampEditor : "",
    slot.valueType,
  ]);
  return { editorKind, valueType };
}

function editablePromptShape(base, contract, choiceDetails, mergeCandidates, validation, currentContext) {
  const { editorKind, valueType, ...prompt } = base;
  if (editorKind) prompt.editorKind = editorKind;
  if (validation) prompt.contractValidation = validation;
  if (choiceDetails.length) {
    prompt.choices = choiceDetails.map(choice => choice.value);
    prompt.choiceDetails = choiceDetails;
  }
  if (mergeCandidates.length) prompt.mergeCandidates = mergeCandidates;
  if (valueType) prompt.valueType = valueType;
  const enabled = choiceDetails.some(choice => !choice.disabled);
  if (contract.slot.valueType === POLICY.referenceValueType && [!choiceDetails.length, !enabled].includes(true)) {
    Object.assign(prompt, fallbackRefPrompt(contract, currentContext));
  }
  return prompt;
}

function mergeCandidateRow(contract, choice, mode, defaultValue) {
  const slot = Object(contract.slot);
  const sourceSubject = firstText([choice.value]);
  const targetSubject = firstText([contract.subject]);
  const targetPredicate = firstText([slot.predicate]);
  const state = mergeCandidateState(choice, defaultValue);
  const label = firstText([choice.label, sourceSubject, targetPredicate]);
  const titleLead = state === POLICY.availableState ? "Bind" : (state === POLICY.currentState ? "Current binding" : "Bind unavailable");
  return {
    id: `${POLICY.relationKind}:${targetSubject}:${targetPredicate}:${sourceSubject}`,
    relationKind: POLICY.relationKind, outcomeClass: mergeCandidateOutcomeClass(state), sourceSubject,
    targetFamily: POLICY.targetFamily, ownerSubject: firstText([contract.parentSubject, contract.subject]),
    targetSubject, targetPredicate, state, title: `${titleLead} ${label}`,
    detail: candidateDetail(contract, choice, state),
    disabledReason: state === POLICY.disabledState ? firstText([choice.reason, POLICY.blockedReasonFallback]) : "",
    previewLabel: firstText([choice.label, sourceSubject]),
    commitDescriptor: {
      operation: mode === "add" ? POLICY.addOperation : POLICY.setOperation,
      subject: targetSubject, predicate: targetPredicate, valueType: POLICY.eligibleValueType, value: sourceSubject,
    },
  };
}

function referenceChoiceDetails(context, compatibleType, existingValues) {
  if (!compatibleType) return [];
  if (!context.currentContext) return [];
  return contextVisibleSubjects(context.prog, context.projection, context.currentContext)
    .sort((left, right) => left.localeCompare(right))
    .map(candidate => {
      const record = Object(context.projection[candidate]);
      const types = Array.isArray(record.isa) ? record.isa : [];
      const compatible = types.includes(compatibleType);
      const label = firstText([record.label, record.name, candidate]);
      const present = existingValues instanceof Set && existingValues.has(candidate);
      const reason = present ? POLICY.referenceExistingReason : (compatible ? "" : `not a ${compatibleType}`);
      return {
        value: candidate, label: label === candidate ? candidate : `${label} (${candidate})`,
        disabled: [present, !compatible].includes(true), reason,
      };
    });
}

function sanitizeRefPart(value) {
  const source = value ? value : POLICY.identityFallback;
  const sanitized = String(source).replace(/[^A-Za-z0-9_.-]+/g, "_").replace(/^_+|_+$/g, "");
  return sanitized ? sanitized : POLICY.identityFallback;
}

function ensureScopedNameAvailable(prog, contextSubject, subject, name, existingBinding, helpers) {
  const conflicts = [
    ...contextBindings(prog, contextSubject)
      .filter(binding => binding.name === name && binding.subject !== existingBinding && binding.memberSubject)
      .map(binding => ({ entry: binding.subject, entryType: "ContextBinding", subject: binding.memberSubject, name: binding.name })),
    ...contextReferenceBindings(prog, contextSubject)
      .filter(reference => reference.name === name)
      .map(reference => ({ entry: reference.subject, entryType: "ContextReference", subject: reference.targetSubject, name: reference.name })),
  ].filter(conflict => conflict.subject);
  if (conflicts.length) helpers.fail(helpers.issue(
    helpers.invalidDiagnostic,
    `Context name ${contextSubject}/${name} is already assigned to ${conflicts[0].subject}.`,
    { context: contextSubject, name, subject, conflicts },
  ));
}

function predicateCompatibilityIssues(record, targetIface, slotMap, predicate, policy) {
  const slot = slotMap.get(predicate);
  if (slot === undefined) {
    if (targetIface.mode === policy.closedMode) {
      return [{ predicate, reason: `${predicate} is not allowed on ${targetIface.type}` }];
    }
    return [];
  }
  const values = valueListFromRecord(record, predicate);
  if (!slotIsMany(slot) && values.length > 1) {
    return [{ predicate, reason: `${predicate} would violate ${targetIface.type}.${predicate} cardinality` }];
  }
  for (const value of values) {
    const reason = validateValueAgainstSlot(slot, value);
    if (reason !== "") return [{ predicate, reason }];
  }
  return [];
}

function requiredSlotCompatibilityIssues(record, targetIface, slot) {
  if (!requiredSlot(slot)) return [];
  const values = valueListFromRecord(record, slot.predicate);
  if (values.length === 0) {
    return [{ predicate: slot.predicate, reason: `${slot.predicate} is required by ${targetIface.type}` }];
  }
  return [];
}

function normalizeRestoreFacts(mutation, helpers) {
  if (!Array.isArray(mutation.facts)) reject(helpers, "restoreDeletedCluster facts must be an explicit array.");
  if (!mutation.facts.length) reject(helpers, "restoreDeletedCluster createFacts requires a non-empty authored fact list.");
  const tupleFacts = mutation.facts.map(factTupleFromMutationFact);
  for (const fact of tupleFacts) {
    const fields = [nonEmptyString(fact.s), nonEmptyString(fact.p), nonEmptyString(fact.o)];
    if (fields.includes(false)) reject(helpers, "restoreDeletedCluster facts must be fully specified positive authored facts.", { fact });
    if (fact.pol !== RESTORE_POLICY.positivePolarity) reject(helpers, "restoreDeletedCluster facts must be fully specified positive authored facts.", { fact });
  }
  return tupleFacts;
}

