function preparePropertyMutation(input, helpers) {
  const { record, combinedFacts, projection, interfaces, subject, operation, mutation, contractPolicyProviders } = input;
  helpers.authorize();
  const { slot } = helpers.ensureSlotWritable(record, interfaces, mutation.predicate);
  const editableContract = helpers.resolveEditableSlotContract(
    combinedFacts, projection, interfaces, subject, mutation.predicate, { contractPolicyProviders },
  );
  const canonicalSlot = editableContract ? editableContract.slot : slot;
  if (operation === POLICY.detachOperation && slot.valueType !== POLICY.referenceValueType) {
    helpers.fail(helpers.issue(
      POLICY.detachDiagnostic,
      `Slot ${slot.predicate} does not support ${POLICY.detachOperation} because it is not a ${POLICY.referenceValueType} slot.`,
      { subject, predicate: slot.predicate, valueType: slot.valueType },
    ), { statusCode: POLICY.badRequestStatus });
  }
  const effectiveOperation = effectivePropertyMutationOperation(operation, slot.cardinality);
  const many = POLICY.manyCardinalities.has(slot.cardinality);
  if (operation === POLICY.addOperation && !many && helpers.currentSingleValue(combinedFacts, subject, slot.predicate) != null) {
    helpers.fail(helpers.issue(
      POLICY.alreadySetDiagnostic,
      `Subject ${subject} already has ${slot.predicate}; ${POLICY.addOperation} only fills an empty slot.`,
      { subject, predicate: slot.predicate, cardinality: slot.cardinality },
    ), { statusCode: POLICY.conflictStatus });
  }
  if (effectiveOperation === POLICY.appendOperation && !many) {
    helpers.fail(helpers.issue(
      POLICY.appendDiagnostic,
      `Slot ${slot.predicate} does not support ${POLICY.appendOperation}.`,
      { subject, predicate: slot.predicate, cardinality: slot.cardinality },
    ));
  }
  return Object.freeze({ slot, canonicalSlot, editableContract, effectiveOperation });
}

